        title = { Text(tr(R.string.manual_entry)) },
        text = { Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
            Text(tr(R.string.manual_kind))
            Box {
                OutlinedButton(enabled = !busy, onClick = { expanded = true }, modifier = Modifier.fillMaxWidth()) {
                    Text(label, modifier = Modifier.weight(1f)); AppIcon(R.drawable.ic_expand_more)
