                DropdownMenu(expanded = expanded, onDismissRequest = { expanded = false }) {
                    listOf("SHIFT", VACATION, SICK, HOLIDAY).forEach { type ->
                        DropdownMenuItem(text = { Text(if (type == "SHIFT") tr(R.string.manual_work_shift) else leaveTypeLabel(type)) },
                            onClick = { kind = type; expanded = false }, enabled = !busy)
